// Rekap TOPIC_LOG bulan lalu -> satu baris MONTHLY_SUMMARY.
// Peringkat dihitung per USER UNIK, bukan per pesan: satu orang yang bertanya
// enam kali tidak boleh menggelembungkan persentase.

const TOP_N = 10;
const NOISE = 'lainnya';  // sapaan/ucapan terima kasih/fragmen — dihitung, tapi tidak diperingkat

function bulanWIB(d) {
  const p = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit'
  }).formatToParts(d);
  return p.find(x => x.type === 'year').value + '-' + p.find(x => x.type === 'month').value;
}

// Bulan sasaran = bulan sebelum bulan berjalan (WIB).
// Dihitung dengan mundur ke tanggal 15 bulan lalu supaya aman dari beda panjang bulan & DST.
const now = new Date();
const nowWIB = bulanWIB(now);
const [y, m] = nowWIB.split('-').map(Number);
const prev = new Date(Date.UTC(m === 1 ? y - 1 : y, m === 1 ? 11 : m - 2, 15, 5, 0, 0));
const target = bulanWIB(prev);

// --- kumpulkan baris bulan sasaran ---
const users = new Set();
const perTopicUsers = {};   // topic -> Set(user)
const perTopicMsgs = {};    // topic -> jumlah pesan
let totalPesan = 0, pesanNoise = 0;
const topikBaru = {};       // label NEW: -> jumlah user

for (const item of $('Read TOPIC_LOG').all()) {
  const r = item.json || {};
  if (String(r.bulan || '').trim() !== target) continue;

  const user = String(r.user_key || '').trim();
  const topic = String(r.topic || '').trim();
  const n = Number(r.jumlah_pesan) || 0;
  if (!user || !topic) continue;

  users.add(user);
  totalPesan += n;

  if (topic === NOISE) { pesanNoise += n; continue; }

  if (!perTopicUsers[topic]) { perTopicUsers[topic] = new Set(); perTopicMsgs[topic] = 0; }
  perTopicUsers[topic].add(user);
  perTopicMsgs[topic] += n;

  if (topic.indexOf('NEW:') === 0) {
    topikBaru[topic] = (topikBaru[topic] || 0) + 1;
  }
}

const totalUser = users.size;

const ranked = Object.keys(perTopicUsers).map(t => ({
  topic: t,
  users: perTopicUsers[t].size,
  messages: perTopicMsgs[t],
  pct: totalUser ? Math.round((perTopicUsers[t].size / totalUser) * 1000) / 10 : 0
})).sort((a, b) => (b.users - a.users) || (b.messages - a.messages) || a.topic.localeCompare(b.topic));

const top = ranked.slice(0, TOP_N);

// Persentase sengaja BOLEH berjumlah >100%: satu user bisa membawa beberapa topik.
const note = totalUser === 0
  ? 'Belum ada data untuk bulan ini.'
  : 'Berdasarkan percakapan yang ditangani VIRA. Chat yang sudah diambil alih Sam tidak ikut terhitung. '
    + 'Satu user bisa menanyakan lebih dari satu topik, jadi jumlah persentase bisa melebihi 100%.';

return [{ json: {
  bulan: target,
  total_user_unik: totalUser,
  total_pesan: totalPesan,
  top_json: JSON.stringify(top),
  topik_baru_json: JSON.stringify(Object.keys(topikBaru).sort()),
  pesan_lainnya: pesanNoise,
  topik_terpakai: ranked.length,
  coverage_note: note,
  generated_at: new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' })
} }];
